import {
	Component,
	Element,
	Event,
	EventEmitter,
	Host,
	Prop,
	State,
	h,
} from "@stencil/core";
/**
 * @since 1.0.8
 * @status experimental
 *
 * @slot - Used for grouping tags in the tag group.
 *
 * @part base - The component's base wrapper.
 * @part tags-container - The tag group container.
 * @part nav - The tab group navigation bar.
 * @part tags - The container that wraps the slotted tags.
 */

@Component({
	tag: "hbr-tag-group",
	styleUrl: "tag-group.scss",
	shadow: true,
})
export class TagGroup {
	body: HTMLElement;
	mutationObserver: MutationObserver;

	resizeObserver: ResizeObserver;
	tagGroup: HTMLElement;
	tags: HTMLElement;
	contentContainer: HTMLElement;

	@Element() host: HTMLHbrTagGroupElement;

	@State() hasScrollControls = false;
	@State() isSelected = false;

	/** Disables the scroll arrows that appear when tags overflow. */
	@Prop() noScrollControls = false;

	/** Set to true to control the tab group's state from the application / framework's side */
	@Prop() uncontrolled = false;

	@Prop({ reflect: true }) variant: "label" | "selectable" = "label"; //"input" is not available yet

	@Prop({ mutable: true }) value: Array<string>;

	@Prop() arialabelledby: string;

	selectableTags = this.variant && this.variant === "selectable";

	/** Emitted when clicking the overflow tag. */
	@Event({ eventName: "hbr-click" }) hbrClick: EventEmitter;

	getAllTags(includeDisabled = false) {
		const slot = this.tags.querySelector("slot");

		return [...slot.assignedElements({ flatten: true })].filter((el: any) => {
			return includeDisabled
				? el.tagName.toLowerCase() === "hbr-tag"
				: el.tagName.toLowerCase() === "hbr-tag" && !el.disabled;
		}) as [HTMLHbrTagElement];
	}

	handleClick(event: MouseEvent) {
		if (this.uncontrolled) return;
		const target = event.target as HTMLElement;
		const tag = target.closest("hbr-tag");
		const tagGroup = tag?.closest("hbr-tag-group");

		// Ensure the target tag is in this tag group
		if (tagGroup !== this.host) {
			return false;
		}
		this.toggleTag(tag);
	}

	handleKeyDown(event: KeyboardEvent) {
		const target = event.target as HTMLElement;
		const tag = target.closest("hbr-tag");
		const tagGroup = tag?.closest("hbr-tag-group");

		// Ensure the target tag is in this tag group
		if (tagGroup !== this.host) {
			return false;
		}

		if (event.key === " ") {
			event.preventDefault();
		}
	}

	toggleTag(tag) {
		tag.selected = !tag.selected;
		tag.setAttribute(
			"aria-checked",
			tag.getAttribute("aria-checked") === "true" ? "false" : "true",
		);
	}

	handleKeyUp(event: KeyboardEvent) {
		let flag = false;
		const { key, target } = event;
		switch (key) {
			case " ":
				this.toggleTag(target);
				flag = true;
				break;

			default:
				break;
		}

		if (flag) {
			event.stopPropagation();
		}
	}

	getNestedTag = (event) => {
		const tag = event.target.closest("hbr-tag");
		if (tag?.nested) {
			if (event.target.tagName.toLowerCase() === "hbr-checkbox") {
				const item = event.target.parentElement;
				this.hbrClick.emit({ event, item, value: item?.value });
			} else {
				this.hbrClick.emit({ event, item: event.detail?.item });
			}
			event.stopPropagation();
		} else {
			// need discussion: do we need this to make it consistent between regular & overflow?
			// this.hbrClick.emit({event, item: event.target});
			// event.stopPropagation();
		}
	};

	render() {
		return (
			<Host>
				<div
					part="base"
					ref={(el) => (this.tagGroup = el)}
					class={{
						"tag-group": true,
						"tag-group--has-scroll-controls": this.hasScrollControls,
					}}
					onHbr-click={this.getNestedTag.bind(this)}
				>
					<div
						role="group"
						aria-labelledby={this.arialabelledby}
						part="tags-container"
						class="tag-group__container"
					>
						<div
							ref={(el) => (this.tags = el)}
							part="tags"
							class="tag-group__tags"
						>
							<slot />
						</div>
					</div>
				</div>
			</Host>
		);
	}
}
